(()=>{const box=document.getElementById('feedback-inbox');if(!box)return;async function load(){const token=sessionStorage.getItem('gtav-admin-token-v2');if(!token){box.textContent='Unlock the dashboard to view reports.';return}box.textContent='Loading reports…';try{const r=await fetch('/api/feedback?admin=1',{headers:{'X-Admin-Token':token}});if(!r.ok)throw Error();const data=await r.json();box.replaceChildren();for(const item of data.items||[]){const article=document.createElement('article');article.className='feedback-inbox-item';for(const [tag,text]of[['small',`${item.created_at} · GTA-${item.id.slice(0,8).toUpperCase()} · ${item.target} · ${item.kind} · ${item.rating}/5`],['h3',item.title],['p',item.message],['p',item.steps],['small',[item.os,item.version,item.device,item.build].filter(Boolean).join(' · ')]]){const node=document.createElement(tag);node.textContent=text;article.append(node)}box.append(article)}if(!box.children.length)box.textContent='No reports yet.'}catch{box.textContent='The inbox could not be loaded. Check your connection and admin access.'}}document.querySelector('[data-tab="feedback"]')?.addEventListener('click',load);document.getElementById('refresh-feedback').onclick=load;document.getElementById('lock-out')?.addEventListener('click',()=>box.replaceChildren())})();
